<div class="auth-shell"><div class="auth-card wide"><span class="eyebrow"><?=e(__('ui.join'))?></span><h1><?=e(__('auth.register'))?></h1><form method="post" action="<?=e(url('/register'))?>" class="form-grid"><?=csrf_field()?><label><?=e(__('auth.first_name'))?><input name="first_name" required value="<?=e(old('first_name'))?>"><?php if(isset($errors['first_name'])):?><small class="field-error"><?=e($errors['first_name'])?></small><?php endif;?></label><label><?=e(__('auth.last_name'))?><input name="last_name" required value="<?=e(old('last_name'))?>"></label><label><?=e(__('auth.email'))?><input name="email" type="email" required value="<?=e(old('email'))?>"><?php if(isset($errors['email'])):?><small class="field-error"><?=e($errors['email'])?></small><?php endif;?></label><label><?=e(__('auth.phone'))?><input name="phone" value="<?=e(old('phone'))?>"></label><label><?=e(__('auth.password'))?><input name="password" type="password" required></label><label><?=e(__('auth.confirm_password'))?><input name="confirm_password" type="password" required><?php if(isset($errors['password'])):?><small class="field-error"><?=e($errors['password'])?></small><?php endif;?></label><label><?=e(__('nav.language'))?><select name="locale"><option value="fr">Français</option><option value="ar">العربية</option><option value="en">English</option></select></label><div></div><button class="btn primary big" type="submit"><?=e(__('auth.submit_register'))?></button></form></div></div><?php clear_old(); ?>
